body {
  min-height: 0 !important;
  margin: 0 auto !important;
}

.desc { white-space: pre-line; }

img { vertical-align: top; max-width: 100%; }
.vmg-lh img, .letter-head img { max-height: 22mm; width: auto; }
.vmg-lhf img, .letter-head-footer img { max-height: 14mm; width: auto; }
.print-format > div:last-child, .print-format p:last-child { margin-bottom: 0 !important; }

